package com.smartmanager.nativeapp;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
/** Stable non-secret identity used to isolate journals belonging to different routers. */
public final class RouterIdentity { private RouterIdentity(){} public static String of(String host,int port,String user,boolean tls){return digest("endpoint|"+host.trim().toLowerCase()+"|"+port+"|"+user+"|"+tls);} public static String device(String board,String architecture,String serial,String version){if(serial==null||serial.trim().isEmpty())throw new IllegalArgumentException("Router identity is not verified");return digest("device|"+serial.trim()+"|"+board+"|"+architecture+"|"+version);} public static boolean matchesDevice(String expected,MapLike resource){return expected!=null&&expected.equals(device(resource.get("board-name"),resource.get("architecture-name"),resource.get("serial-number"),resource.get("version")));} private static String digest(String s){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:d)b.append(String.format(java.util.Locale.ROOT,"%02x",x&255));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}} public interface MapLike{String get(String key);} }
